<?php
require __DIR__.'/../bootstrap.php';require_admin();
$durations=['1h'=>['1 Hour',3600],'6h'=>['6 Hours',21600],'24h'=>['24 Hours / 1 Day',86400],'1w'=>['1 Week',604800],'1m'=>['1 Month',2592000],'1y'=>['1 Year',31536000],'perm'=>['Permanent',null]];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)post('action');if($action==='block_ip'){ $ip=trim((string)post('ip'));$d=$durations[(string)post('duration','24h')]??$durations['24h'];if(filter_var($ip,FILTER_VALIDATE_IP)){ $hash=hash_hmac('sha256',$ip,app_secret());$exp=$d[1]===null?null:date('Y-m-d H:i:s',time()+$d[1]);db()->prepare('INSERT INTO file_abuse_blocks(ip_hash,ip_encrypted,reason,expires_at,created_at) VALUES(?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE ip_encrypted=VALUES(ip_encrypted),reason=VALUES(reason),expires_at=VALUES(expires_at)')->execute([$hash,encrypt_secret($ip),'Admin abuse block',$exp]);db()->prepare('INSERT INTO file_abuse_history(ip_hash,ip_encrypted,action,duration_label,reason,admin_user_id,expires_at,created_at) VALUES(?,?,?,?,?,?,?,NOW())')->execute([$hash,encrypt_secret($ip),'block',$d[0],'Admin abuse block',(int)current_user()['id'],$exp]);flash('success',$ip.' blocked for '.$d[0].'.');}else flash('error','Enter a valid IP address.');redirect('/admin/files/');}
if($action==='unblock'){ $id=(int)post('id');$s=db()->prepare('SELECT * FROM file_abuse_blocks WHERE id=?');$s->execute([$id]);$r=$s->fetch();if($r){db()->prepare('DELETE FROM file_abuse_blocks WHERE id=?')->execute([$id]);db()->prepare('INSERT INTO file_abuse_history(ip_hash,ip_encrypted,action,duration_label,reason,admin_user_id,expires_at,created_at) VALUES(?,?,?,?,?,?,?,NOW())')->execute([$r['ip_hash'],(string)($r['ip_encrypted']??''),'unblock',null,'Admin unblock',(int)current_user()['id'],null]);}flash('success','IP unblocked.');redirect('/admin/files/');}
if($action==='clear_history'){db()->exec('DELETE FROM file_abuse_history');flash('success','Block/unblock history cleared.');redirect('/admin/files/');}
$id=(int)post('id');if(in_array($action,['clean','quarantine','delete'],true)&&$id>0){
    $s=db()->prepare('SELECT * FROM file_objects WHERE id=?');$s->execute([$id]);$f=$s->fetch();
    if(!$f){flash('error','File not found.');redirect('/admin/files/');}
    if($action==='clean'){db()->prepare("UPDATE file_objects SET scan_status='clean',status='clean',updated_at=NOW() WHERE id=?")->execute([$id]);flash('success','File marked clean.');redirect('/admin/files/');}
    if($action==='quarantine'){db()->prepare("UPDATE file_objects SET scan_status='infected',status='quarantined',updated_at=NOW() WHERE id=?")->execute([$id]);flash('success','File quarantined.');redirect('/admin/files/');}
    if($action==='delete'){
        $driver=(string)($f['storage_driver']??'local');$storageOk=true;
        if($driver==='local'){
            $path=file_local_path($f);if(is_file($path)&&!@unlink($path))$storageOk=false;
        }elseif($driver==='s3'){
            if(!s3_cfg_ok()){$storageOk=false;}else{[$code]=s3_request('DELETE',(string)$f['object_key']);$storageOk=($code>=200&&$code<300)||$code===404;}
        }else{
            $storageOk=false;
        }
        if(!$storageOk){flash('error','The file record was not deleted because the storage object could not be removed.');redirect('/admin/files/');}
        try{db()->prepare("DELETE FROM media_assets WHERE source_category='Shared Files' AND source_ref_id=?")->execute([$id]);}catch(Throwable $ignored){}
        db()->prepare("UPDATE file_objects SET status='deleted',updated_at=NOW() WHERE id=?")->execute([$id]);flash('success','File deleted and storage object removed.');redirect('/admin/files/');
    }
}
}
$files=db()->query("SELECT f.*,u.username FROM file_objects f JOIN users u ON u.id=f.user_id WHERE f.status<>'deleted' ORDER BY f.created_at DESC LIMIT 300")->fetchAll();$blocks=db()->query('SELECT * FROM file_abuse_blocks WHERE expires_at IS NULL OR expires_at>NOW() ORDER BY created_at DESC')->fetchAll();$history=db()->query('SELECT h.*,u.username FROM file_abuse_history h LEFT JOIN users u ON u.id=h.admin_user_id ORDER BY h.created_at DESC LIMIT 300')->fetchAll();
require __DIR__.'/../includes/header.php';?><div class="files-admin-page"><div class="page-head"><div><span class="eyebrow">ADMIN GOVERNANCE</span><h1>File moderation & IP management</h1><p>Moderate files, block abusive IPs with explicit durations, and audit every block/unblock action.</p></div></div>
<section class="card"><h2>Block an IP</h2><form method="post" class="grid-main"><?=csrf_field()?><label>IP address<input name="ip" required placeholder="203.0.113.10"></label><label>Duration<select name="duration"><?php foreach($durations as $k=>$d):?><option value="<?=$k?>"><?=e($d[0])?></option><?php endforeach;?></select></label><button class="btn" name="action" value="block_ip">Block IP</button></form></section>
<section class="card"><div class="row"><h2>Currently blocked</h2><span class="badge"><?=count($blocks)?> active</span></div><div class="table-wrap"><table><thead><tr><th>IP</th><th>Reason</th><th>Expires</th><th>Created</th><th>Action</th></tr></thead><tbody><?php foreach($blocks as $b):$ip=$b['ip_encrypted']?decrypt_secret((string)$b['ip_encrypted']):'Legacy / unavailable';?><tr><td data-label="IP"><code class="credential-box"><?=e($ip)?></code></td><td data-label="Reason"><?=e($b['reason'])?></td><td data-label="Expires"><?=e($b['expires_at']?:'Permanent')?></td><td data-label="Created"><?=e($b['created_at'])?></td><td data-label="Action"><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$b['id']?>"><button class="btn small" name="action" value="unblock">Unblock</button></form></td></tr><?php endforeach;if(!$blocks):?><tr><td colspan="5">No active IP blocks.</td></tr><?php endif;?></tbody></table></div></section>
<section class="card"><div class="row"><h2>Block / Unblock History</h2><form method="post" onsubmit="return confirm('Clear all history?')"><?=csrf_field()?><button class="btn small danger" name="action" value="clear_history">Clear History</button></form></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>IP</th><th>Action</th><th>Duration</th><th>Admin</th></tr></thead><tbody><?php foreach($history as $h):$display=!empty($h['ip_encrypted'])?decrypt_secret((string)$h['ip_encrypted']):'Historical / unavailable';?><tr><td data-label="Time"><?=e($h['created_at'])?></td><td data-label="IP"><code><?=e($display)?></code></td><td data-label="Action"><?=e(strtoupper($h['action']))?></td><td data-label="Duration"><?=e($h['duration_label']?:'—')?></td><td data-label="Admin"><?=e($h['username']?:'System')?></td></tr><?php endforeach;if(!$history):?><tr><td colspan="5">No history yet.</td></tr><?php endif;?></tbody></table></div></section>
<section class="card"><h2>File review</h2><div class="table-wrap"><table><thead><tr><th>File</th><th>User</th><th>Size</th><th>Scan</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($files as $f):?><tr><td data-label="File"><?=e($f['original_name'])?></td><td data-label="User"><?=e($f['username'])?></td><td data-label="Size"><?=e(storage_human((int)$f['size_bytes']))?></td><td data-label="Scan"><?=e($f['scan_status'])?></td><td data-label="Status"><?=e($f['status'])?></td><td data-label="Action"><form method="post" class="file-review-actions"><?php echo csrf_field();?><input type="hidden" name="id" value="<?=$f['id']?>"><button class="btn small" name="action" value="clean">Mark clean</button> <button class="btn small danger" name="action" value="quarantine">Quarantine</button> <button class="btn small danger" name="action" value="delete" onclick="return confirm('Delete object permanently?')">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require __DIR__.'/../includes/footer.php';
